//! Sound effects and music. Sounds live in `assets/sounds/` and are
//! generated by `tools/make_sounds.py`; a file of the same name replaces one.

use bevy::audio::Volume;
use bevy::prelude::*;

use crate::day_cycle::Phase;
use crate::fx::Cue;
use crate::rng::Rng;
use crate::save::Settings;

const MUSIC_FADE_SECS: f32 = 2.0;

pub struct SoundPlugin;

impl Plugin for SoundPlugin {
    fn build(&self, app: &mut App) {
        app.init_resource::<Sounds>()
            .init_resource::<CurrentMusic>()
            .add_systems(Update, (play_cues, choose_music, fade_music));
    }
}

#[derive(Resource)]
pub struct Sounds {
    bell: Handle<AudioSource>,
    coins: Handle<AudioSource>,
    chime: Handle<AudioSource>,
    midnight: Handle<AudioSource>,
    crash: Handle<AudioSource>,
    click: Handle<AudioSource>,
    sigh: Handle<AudioSource>,
    evening_music: Handle<AudioSource>,
    night_ambience: Handle<AudioSource>,
}

impl FromWorld for Sounds {
    fn from_world(world: &mut World) -> Self {
        let assets = world.resource::<AssetServer>();
        Self {
            bell: assets.load("sounds/bell.ogg"),
            coins: assets.load("sounds/coins.ogg"),
            chime: assets.load("sounds/chime.ogg"),
            midnight: assets.load("sounds/midnight.ogg"),
            crash: assets.load("sounds/crash.ogg"),
            click: assets.load("sounds/click.ogg"),
            sigh: assets.load("sounds/sigh.ogg"),
            evening_music: assets.load("sounds/evening_music.ogg"),
            night_ambience: assets.load("sounds/night_ambience.ogg"),
        }
    }
}

fn play_cues(
    mut commands: Commands,
    mut cues: MessageReader<Cue>,
    sounds: Res<Sounds>,
    settings: Res<Settings>,
    mut rng: ResMut<Rng>,
) {
    for cue in cues.read() {
        if !settings.sound {
            continue;
        }
        let (sound, volume, vary) = match cue {
            Cue::GhostEnters => (&sounds.bell, 0.5, false),
            Cue::Paid | Cue::ChangeGiven => (&sounds.coins, 0.7, true),
            Cue::Ascend(_) => (&sounds.chime, 0.7, false),
            Cue::Knock(_) => (&sounds.crash, 0.6, true),
            Cue::Disappointed => (&sounds.sigh, 0.6, false),
            Cue::Click => (&sounds.click, 0.5, true),
            Cue::Midnight => (&sounds.midnight, 0.8, false),
        };
        // A little pitch variation keeps repeated sounds from feeling canned.
        let speed = if vary { rng.range(0.93, 1.07) } else { 1.0 };
        commands.spawn((
            AudioPlayer::new(sound.clone()),
            PlaybackSettings {
                volume: Volume::Linear(volume * settings.effects),
                speed,
                ..PlaybackSettings::DESPAWN
            },
        ));
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Track {
    Evening,
    Night,
}

#[derive(Resource, Default)]
struct CurrentMusic(Option<Track>);

/// A playing music track and where its volume is heading.
#[derive(Component)]
struct Music {
    volume: f32,
    target: f32,
}

fn choose_music(
    mut commands: Commands,
    phase: Res<State<Phase>>,
    settings: Res<Settings>,
    sounds: Res<Sounds>,
    mut current: ResMut<CurrentMusic>,
    mut playing: Query<&mut Music>,
) {
    let wanted = settings.sound.then(|| match phase.get() {
        Phase::Night => Track::Night,
        _ => Track::Evening,
    });
    if wanted == current.0 {
        return;
    }
    current.0 = wanted;
    for mut music in &mut playing {
        music.target = 0.0;
    }
    let Some(track) = wanted else { return };
    let (handle, target) = match track {
        Track::Evening => (&sounds.evening_music, 0.6),
        Track::Night => (&sounds.night_ambience, 0.8),
    };
    commands.spawn((
        AudioPlayer::new(handle.clone()),
        PlaybackSettings {
            volume: Volume::SILENT,
            ..PlaybackSettings::LOOP
        },
        Music {
            volume: 0.0,
            target,
        },
    ));
}

/// Fades music in and out on real time, so it also works while paused.
fn fade_music(
    mut commands: Commands,
    time: Res<Time<Real>>,
    settings: Res<Settings>,
    mut playing: Query<(Entity, &mut Music, &mut AudioSink)>,
) {
    let step = time.delta_secs() / MUSIC_FADE_SECS;
    for (entity, mut music, mut sink) in &mut playing {
        let diff = music.target - music.volume;
        music.volume += diff.clamp(-step, step);
        sink.set_volume(Volume::Linear(music.volume * settings.music));
        if music.target == 0.0 && music.volume <= 0.0 {
            commands.entity(entity).despawn();
        }
    }
}
